UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (6761, 'Пригодницько-комедійний серіал про Джейка Лонґа — 13-річного хлопця азійсько-американського походження, який намагається знайти баланс між життям нью-йоркського підлітка-скейтера та опануванням містичних сил у своїй таємній іпостасі Американського Дракона — захисника й охоронця всіх магічних створінь, що таємно живуть серед людей.'),
  (3026, 'Родина ховається у протирадіаційному бункері, намагаючись уникнути небезпечного спалаху.'),
  (6789, 'Життя і пригоди кота і пса з унікальною особливістю: вони з''єднані — буквально. Вони ділять одне тіло: з одного боку — голова Пса, з іншого — голова Кота. На додачу до цієї дилеми — Кіт постійно роздратований через Пса, здебільшого через Псову дурість та власну вередливість Кота. Персонажі: Кіт — розумніший із двох братів, він завжди вигадує якийсь план, щоб змусити брата заспокоїтися і не бути побитим та покаліченим. Хоча більшість цих планів передбачають маніпуляції з довірливим розумом Пса, вони часто б''ють по самому Коту, на його превеликий жаль. Можливо, це не завжди помітно, але він глибоко любить і піклується про свого брата Пса. Пес — більш зворушливий із двох братів, Пес обожнює грати, веселитися та грати ще більше, він любить бейсбол і ловити фрізбі, м''ячі, палички тощо. Він дуже дружелюбний і щасливий, але має межу терпіння. Він дуже чутливий, і коли йому щось не вдається, почувається жахливо і нікчемно.'),
  (5843, 'Підставлена як винуватиця корпоративного шахрайства, молода Макарена Ферейро потрапляє до жіночої в''язниці суворого режиму, оточена жорстокими, безжальними злочинницями, у цьому напруженому, провокативному іспанському трилері.'),
  (5897, 'Один постріл, одна смерть, одна мить поза часом, що безповоротно пов''язує вісім свідомостей у різних куточках світу, поринаючи їх у життя, таємниці та смертельну небезпеку одне одного. Звичайні люди, що раптово перероджуються як «сенсейти».'),
  (104, 'У розпалі Першої світової війни двоє молодих британських солдатів мають перетнути ворожу територію та доставити повідомлення, яке зупинить смертоносну атаку на сотні солдатів.'),
  (6398, 'Корейський імператор Лі Ґон намагається закрити двері до паралельного світу, відкритого демонами; детективка намагається захистити людей і того, кого кохає.'),
  (6898, 'Після того як Месників поглинає зомбі-чума, відчайдушна група вцілілих знаходить ключ до знищення суперсильних мерців, мчачи крізь антиутопічний ландшафт і ризикуючи життям заради порятунку свого світу.'),
  (859, 'Слідкуйте за пригодами групи молодих мультиплікаційних персонажів, які навчаються в Акме-Луноверситеті, щоб стати наступним поколінням героїв серії Looney Tunes.'),
  (6362, 'Незвичайне відкриття надихає двох людських принців та ельфійську вбивцю об''єднатися в епічному квесті, щоб принести мир їхнім ворогуючим землям.'),
  (6494, 'Коли блискавка влучає в поліцейську криміналістичну лабораторію, суміш електрично заряджених речовин обливає хіміка Баррі Аллена, перетворюючи його на найшвидшу людину на Землі — Флеша.'),
  (5866, 'За часів правління Галактичної Імперії колишній магістр-джедай Обі-Ван Кенобі вирушає на надважливу місію — протистояти колишнім союзникам, що стали ворогами, та зустріти гнів Імперії.'),
  (6166, 'Через нещасний випадок під час парапланеризму південнокорейська спадкоємиця опиняється в Північній Кореї — і в житті армійського офіцера, який вирішує допомогти їй сховатися.'),
  (6715, 'Тридцять років тому в тихому містечку Вотербері вбивця, відомий як «Кат», убив батьків Сари Беннетт. Тепер Сара з чоловіком Діланом повернулися до міста, але вона опиняється в центрі серії жахливих вбивств, пов''язаних із сімома смертними гріхами.'),
  (2465, 'Одного мирного дня на Землі двоє залишків армії Фрізи — Сорбет і Таґома — прибувають у пошуках Драконячих Куль з метою воскресити Фрізу. Їм це вдається, і Фріза вирушає мститися саянам.'),
  (6045, 'Дженніфер Волтерс веде непросте життя незаміжньої тридцятирічної адвокатки, яка до того ж є зеленою двометровою суперсильною Галкою.')
) AS v(id, overview_uk) WHERE content.id = v.id;
